import type { DrugInteraction, DrugMonograph, Reference } from '../types';

/**
 * DEMO KNOWLEDGE BASE — educational summaries written for the demo from widely
 * documented public labelling. It is intentionally small and is NOT a clinical
 * reference. Production must replace this with a licensed, versioned source
 * (e.g. FDA SPL labels via openFDA + RxNorm, or a commercial interaction database).
 */

const REVIEWED = '2026-09-15T00:00:00.000Z';

const dailyMed = (drug: string): Reference => ({
  title: `${drug} — prescribing information`,
  publisher: 'U.S. National Library of Medicine · DailyMed',
  url: `https://dailymed.nlm.nih.gov/dailymed/search.cfm?query=${encodeURIComponent(drug)}`,
});
const medlinePlus = (drug: string): Reference => ({
  title: `${drug} — drug information`,
  publisher: 'MedlinePlus (NIH)',
  url: `https://medlineplus.gov/druginformation.html`,
});

