export function findDrug(id: string) {
  return DRUGS.find((d) => d.id === id);
}

export function searchDrugs(q: string) {
  const s = q.trim().toLowerCase();
  if (!s) return DRUGS;
  return DRUGS.filter(
    (d) =>
      d.generic.toLowerCase().includes(s) ||
      d.brands.some((b) => b.toLowerCase().includes(s)) ||
      d.drugClass.toLowerCase().includes(s),
  );
}
